        $("#speedup").checked = setting.speedup;

        $("#restock").checked = setting.restock;

        $("#premove").disabled = !allowMove;

        $("#preset").value = setting.preset;

        $("#preset2").value = setting.preset2;

        $("#preset3").value = setting.preset3;

        $("#skinid").value = setting.skinid;

